import { useEffect, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent, type ReactNode } from "react"

// #region magnet
// Pure: the magnetic pull, exactly as the Bunkum template's footer. The test lifts this region.

/** The pill follows the pointer by this share of its distance from the pill's centre (x, y). */
export const PULL = [0.22, 0.32] as const
/** The label inside a CTA pill moves a little further on top, so it floats inside the pill. */
export const PULL_INNER = [0.12, 0.16] as const
export const magnetTransform = (dx: number, dy: number, k: readonly [number, number]) => "translate(" + (dx * k[0]).toFixed(1) + "px," + (dy * k[1]).toFixed(1) + "px)"
/** The fan's lightbox cycles its three drawings. */
export const step = (i: number, by: number, n: number) => (n > 0 ? (((i + by) % n) + n) % n : 0)
// #endregion

/* ------------------------------------------------------------- content */

type Action = { label?: string; href?: string; onClick?: () => void }
export type WeirdBriefCtaProps = {
  /** The huge headline. A "\n" breaks the line. */
  headline?: string
  /** The line under the headline. */
  body?: string
  /** Shown on the ghost pill; clicking it copies this address. */
  email?: string
  /** The magnetic primary pill. With `href` it renders a link, otherwise a button. */
  commissionAction?: Action
  /** Toast shown after the address is copied. */
  copiedMessage?: string
  /** Minimum height of the section. A definite length; the section grows past it if its content needs to. */
  height?: string
  /** Alias for `height`; wins when both are set. */
  minHeight?: string
  className?: string
  style?: CSSProperties
}

/** The fan, back to front: picture key, caption, resting tilt. */
const FAN: [string, string, string][] = [
  ["a3", "Cloud sketch", "-7deg"],
  ["b7", "Gardener bot", "6deg"],
  ["b5", "Sock ghost", "-1deg"],
]

/* ------------------------------------------------------------- styles */

const CSS =
  ".bkm-root{--blue:#2731e8;--deep:#0d137a;--butter:#ffe98a;--ink:#0c0c10;--paper:#f6f1e3;position:relative;overflow:clip;background:var(--ink);color:var(--paper);font-family:BkmSans,ui-sans-serif,system-ui,sans-serif;-webkit-font-smoothing:antialiased;isolation:isolate}" +
  ".dark .bkm-root{--ink:#08080b}" +
  ".bkm-root *{box-sizing:border-box}" +
  ".bkm-root svg,.bkm-root img{max-width:none}" +
  ".bkm-mono{font-family:BkmMono,ui-monospace,monospace;font-size:11px;line-height:1.35;letter-spacing:.06em;text-transform:uppercase}" +
  ".bkm-speck{background-color:var(--blue);background-image:radial-gradient(circle at 30% 40%,rgba(255,255,255,.14) 0 1.2px,transparent 1.8px),radial-gradient(circle at 70% 60%,rgba(0,0,0,.22) 0 1.6px,transparent 2.3px),radial-gradient(circle at 50% 50%,rgba(255,255,255,.08) 0 2.4px,transparent 3px);background-size:37px 41px,53px 47px,113px 97px}" +
  /* pills */
  ".bkm-pill{position:relative;display:flex;align-items:center;height:48px;padding:0 14px 0 18px;border:0;border-radius:51px;background:var(--butter);color:var(--deep);font:inherit;font-size:17px;font-weight:700;letter-spacing:-.015em;text-decoration:none;cursor:pointer;pointer-events:auto;transition:transform .55s cubic-bezier(.2,1.6,.4,1)}" +
  ".bkm-pill[data-near]{transition:transform .1s linear}" +
  ".bkm-pill:focus-visible{outline:2px solid var(--butter);outline-offset:3px}" +
  /* the section */
  ".bkm-foot{position:relative;z-index:4;padding:clamp(80px,14vh,150px) 18px 22px;color:var(--butter)}" +
  ".bkm-brief{padding-bottom:clamp(64px,12vh,140px)}" +
  ".bkm-big{margin:0;font-weight:800;font-size:clamp(54px,10.5vw,190px);line-height:.84;letter-spacing:-.06em;color:var(--butter)}" +
  ".bkm-sub{max-width:34ch;margin:clamp(22px,4vh,36px) 0 0;font-size:clamp(16px,1.4vw,21px);font-weight:700;line-height:1.3}" +
  ".bkm-ctas{display:flex;flex-wrap:wrap;gap:12px;margin-top:clamp(26px,5vh,44px)}" +
  ".bkm-cta{height:56px;padding:0 24px;font-size:16px;gap:12px}" +
  ".bkm-cta.bkm-ghost{background:transparent;color:var(--butter);box-shadow:inset 0 0 0 2px var(--butter)}" +
  ".bkm-cta>span{display:inline-flex;align-items:center;gap:12px;transition:transform .55s cubic-bezier(.2,1.6,.4,1)}" +
  ".bkm-cta[data-near]>span{transition:transform .1s linear}" +
  ".bkm-cta svg{width:16px;height:16px}" +
  /* the fan */
  ".bkm-fan{position:absolute;right:clamp(24px,7vw,130px);top:clamp(90px,15vh,160px);width:clamp(190px,21vw,320px);aspect-ratio:1;padding:0;border:0;background:none;cursor:pointer}" +
  ".bkm-fan i{position:absolute;inset:0;border-radius:14px;border:3px solid var(--ink);background-size:cover;background-position:center;box-shadow:7px 9px 0 var(--deep);transform:rotate(var(--r));transition:transform .7s cubic-bezier(.2,1.5,.4,1)}" +
  ".bkm-fan:hover i:nth-child(1),.bkm-fan:focus-visible i:nth-child(1){transform:translate(-46%,10%) rotate(-17deg)}" +
  ".bkm-fan:hover i:nth-child(2),.bkm-fan:focus-visible i:nth-child(2){transform:translate(46%,10%) rotate(15deg)}" +
  ".bkm-fan:hover i:nth-child(3),.bkm-fan:focus-visible i:nth-child(3){transform:translateY(-12%) rotate(-2deg)}" +
  ".bkm-fan img{position:absolute;right:-16%;bottom:-18%;width:34%;height:auto;transform:rotate(8deg);transition:transform .7s cubic-bezier(.2,1.5,.4,1);pointer-events:none}" +
  ".bkm-fan:hover img{transform:rotate(-4deg) translate(10%,-24%)}" +
  ".bkm-fan:focus-visible{outline:2px solid var(--butter);outline-offset:8px;border-radius:16px}" +
  /* lightbox */
  ".bkm-lb{position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:24px;background:rgba(12,12,16,.86);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);animation:bkm-fade .3s both}" +
  "@keyframes bkm-fade{from{opacity:0}}" +
  ".bkm-lb figure{margin:0;display:flex;flex-direction:column;align-items:center;gap:14px}" +
  ".bkm-lb img{display:block;width:min(560px,82vw,64vh);height:auto;aspect-ratio:1;border-radius:4px;animation:bkm-pop .5s cubic-bezier(.2,1.4,.4,1) both}" +
  "@keyframes bkm-pop{from{transform:scale(.6);opacity:0}}" +
  ".bkm-lb figcaption{display:flex;gap:16px;align-items:center;color:var(--paper)}" +
  ".bkm-lbbtn{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;border:1.5px solid var(--paper);background:none;color:var(--paper);cursor:pointer;font:inherit;font-size:18px}" +
  ".bkm-lbbtn:focus-visible{outline:2px solid var(--butter);outline-offset:3px}" +
  /* toast + context label (the system cursor stays) */
  ".bkm-toast{position:fixed;left:50%;bottom:24px;z-index:80;transform:translate(-50%,calc(100% + 48px));padding:12px 18px;border-radius:999px;background:var(--butter);color:var(--deep);font-weight:800;font-size:14px;transition:transform .5s cubic-bezier(.2,1.5,.4,1);pointer-events:none;white-space:nowrap}" +
  ".bkm-toast[data-on]{transform:translate(-50%,0)}" +
  ".bkm-cursor{display:none;position:fixed;left:0;top:0;z-index:90;pointer-events:none}" +
  ".bkm-clab{position:absolute;left:16px;top:16px;padding:6px 10px;border-radius:999px;background:var(--butter);color:var(--deep);white-space:nowrap;opacity:0;transform:scale(.5);transform-origin:0 0;transition:transform .3s cubic-bezier(.2,1.5,.4,1),opacity .15s}" +
  ".bkm-cursor[data-label] .bkm-clab{opacity:1;transform:none}" +
  "@media (hover:hover) and (pointer:fine){.bkm-cursor{display:block}}" +
  /* small screens */
  "@media (max-width:900px){.bkm-fan{display:none}}" +
  "@media (max-width:640px){.bkm-pill{height:38px;padding:0 10px 0 12px;font-size:14px}}" +
  "@media (prefers-reduced-motion:reduce){.bkm-root *{animation:none!important;transition-duration:.01ms!important;transition-delay:0s!important}}"

/* ------------------------------------------------------------- helpers */

const Arrow = () => (
  <svg viewBox="0 0 20 20" aria-hidden="true">
    <path d="M2 10h15M12 5l5 5-5 5" stroke="currentColor" strokeWidth="1.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)
const bg = (k: string) => ({ backgroundImage: "var(--bk-" + k + ")" }) as CSSProperties
const f = (n: number) => (Math.round(n * 10) / 10).toString()

export default function WeirdBriefCta({
  headline = "Got a weird\nbrief?",
  body = "Send it over. The odder the better: we reply within two sleeps, with a doodle.",
  email = "hello@bunkum.studio",
  commissionAction = { label: "Start a commission" },
  copiedMessage = "Copied. We reply within two sleeps.",
  height = "480px",
  minHeight,
  className,
  style,
}: WeirdBriefCtaProps) {
  const cursorRef = useRef(null as HTMLDivElement | null)
  const labelRef = useRef(null as HTMLSpanElement | null)
  const [lb, setLb] = useState(-1)
  const [toast, setToast] = useState({ text: "", on: false })
  const toastTimer = useRef(0)
  const s = useRef({
    fine: false,
    still: false,
    px: -1,
    py: -1,
    over: false,
    label: "",
    magnet: null as HTMLElement | null,
    magnetBox: null as DOMRect | null,
    raf: 0,
    cache: new WeakMap() as WeakMap<object, Record<string, string>>,
  })

  // a write cache: a style is only touched when its value changes
  const put = (el: HTMLElement | null | undefined, prop: string, val: string) => {
    if (!el) return
    const c = s.current.cache
    let m = c.get(el)
    if (!m) c.set(el, (m = {}))
    if (m[prop] === val) return
    m[prop] = val
    ;(el.style as unknown as Record<string, string>)[prop] = val
  }
  const flag = (el: HTMLElement | null | undefined, name: string, on: boolean) => {
    if (!el) return
    if (on !== el.hasAttribute(name)) on ? el.setAttribute(name, "") : el.removeAttribute(name)
  }
  const say = (text: string) => {
    setToast({ text, on: true })
    window.clearTimeout(toastTimer.current)
    toastTimer.current = window.setTimeout(() => setToast((t) => ({ ...t, on: false })), 2800)
  }

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return
    const rm = window.matchMedia("(prefers-reduced-motion: reduce)")
    const fp = window.matchMedia("(hover: hover) and (pointer: fine)")
    const sync = () => {
      s.current.still = rm.matches
      s.current.fine = fp.matches
      if (!fp.matches || rm.matches) releaseMagnet()
    }
    sync()
    rm.addEventListener("change", sync)
    fp.addEventListener("change", sync)
    return () => {
      rm.removeEventListener("change", sync)
      fp.removeEventListener("change", sync)
      const st = s.current
      if (st.raf) window.cancelAnimationFrame(st.raf)
      st.raf = 0
      window.clearTimeout(toastTimer.current)
    }
  }, [])

  // ---- the frame: the context label follows the mouse (writes only)
  const frame = () => {
    const st = s.current
    st.raf = 0
    if (st.fine && st.over) put(cursorRef.current, "transform", "translate3d(" + f(st.px) + "px," + f(st.py) + "px,0)")
  }
  const schedule = () => {
    const st = s.current
    if (!st.raf && typeof window !== "undefined") st.raf = window.requestAnimationFrame(frame)
  }

  // ---- lightbox keys
  useEffect(() => {
    if (lb < 0) return
    const onKey = (ev: KeyboardEvent) => {
      if (ev.key === "Escape") setLb(-1)
      else if (ev.key === "ArrowRight") setLb((i) => step(i, 1, FAN.length))
      else if (ev.key === "ArrowLeft") setLb((i) => step(i, -1, FAN.length))
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [lb])

  // ---- pointer: context label, magnets (mouse only)
  const releaseMagnet = () => {
    const st = s.current
    const m = st.magnet
    if (m) {
      m.style.transform = ""
      m.removeAttribute("data-near")
      const inner = m.firstElementChild as HTMLElement | null
      if (inner && m.classList.contains("bkm-cta")) inner.style.transform = ""
    }
    st.magnet = null
    st.magnetBox = null
  }
  const onMove = (ev: ReactPointerEvent<HTMLElement>) => {
    const st = s.current
    if (ev.pointerType !== "mouse") return
    st.px = ev.clientX
    st.py = ev.clientY
    st.over = true
    const t = ev.target as Element
    const hit = t.closest ? (t.closest("[data-cursor]") as HTMLElement | null) : null
    const label = hit ? hit.getAttribute("data-cursor") || "" : ""
    if (label !== st.label) {
      st.label = label
      if (labelRef.current) labelRef.current.textContent = label
      flag(cursorRef.current, "data-label", !!label)
    }
    const mag = st.fine && !st.still && t.closest ? (t.closest("[data-magnet]") as HTMLElement | null) : null
    if (mag !== st.magnet) {
      releaseMagnet()
      if (mag) {
        st.magnet = mag
        st.magnetBox = mag.getBoundingClientRect()
        mag.setAttribute("data-near", "")
      }
    }
    if (st.magnet && st.magnetBox) {
      const bx = st.magnetBox
      const dx = ev.clientX - (bx.left + bx.width / 2)
      const dy = ev.clientY - (bx.top + bx.height / 2)
      st.magnet.style.transform = magnetTransform(dx, dy, PULL)
      const inner = st.magnet.firstElementChild as HTMLElement | null
      if (inner && st.magnet.classList.contains("bkm-cta")) inner.style.transform = magnetTransform(dx, dy, PULL_INNER)
    }
    schedule()
  }
  const onLeave = (ev: ReactPointerEvent<HTMLElement>) => {
    const st = s.current
    if (ev.pointerType === "mouse") st.over = false
    flag(cursorRef.current, "data-label", false)
    st.label = ""
    releaseMagnet()
    schedule()
  }

  const copyEmail = () => {
    const done = () => say(copiedMessage)
    if (typeof navigator !== "undefined" && navigator.clipboard) navigator.clipboard.writeText(email).then(done, () => say(email))
    else say(email)
  }

  const vars = {} as Record<string, string>
  for (const [k] of FAN) vars["--bk-" + k] = "url(" + IMG[k] + ")"
  const rootStyle = { ...vars, minHeight: minHeight || height, ...style } as CSSProperties
  const C = commissionAction
  const lines = headline.split("\n")

  return (
    <section
      className={"bkm-root bkm-foot bkm-speck bkm-brief" + (className ? " " + className : "")}
      style={rootStyle}
      aria-label={lines.join(" ")}
      onPointerMove={onMove}
      onPointerLeave={onLeave}
    >
      <style>{FONTS + CSS}</style>
      <h2 className="bkm-big">
        {lines.map((l, i) => (
          <span key={i}>
            {i > 0 && <br />}
            {l}
          </span>
        ))}
      </h2>
      <button type="button" className="bkm-fan" data-cursor="Fan out" aria-label="Open the latest three drawings" onClick={() => setLb(FAN.length - 1)}>
        {FAN.map(([k, , r]) => (
          <i key={k} style={{ ...bg(k), "--r": r } as CSSProperties} />
        ))}
        <img src={IMG.s2} alt="" width={196} height={300} />
      </button>
      <p className="bkm-sub">{body}</p>
      <div className="bkm-ctas">
        <ActionEl a={C} className="bkm-pill bkm-cta" cursor="Let's go">
          <span>
            {C.label || "Start a commission"}
            <Arrow />
          </span>
        </ActionEl>
        <button type="button" className="bkm-pill bkm-cta bkm-ghost" data-magnet="" data-cursor="Copy" onClick={copyEmail}>
          <span>{email}</span>
        </button>
      </div>

      {lb >= 0 && (
        <div className="bkm-lb" role="dialog" aria-modal="true" aria-label={FAN[lb][1]} onClick={() => setLb(-1)}>
          <figure onClick={(e) => e.stopPropagation()}>
            <img key={lb} src={IMG[FAN[lb][0]]} alt={FAN[lb][1]} width={560} height={560} />
            <figcaption>
              <button type="button" className="bkm-lbbtn" aria-label="Previous" onClick={() => setLb((i) => step(i, -1, FAN.length))}>
                ←
              </button>
              <span className="bkm-mono">
                {FAN[lb][1]} · {lb + 1}/{FAN.length}
              </span>
              <button type="button" className="bkm-lbbtn" aria-label="Next" onClick={() => setLb((i) => step(i, 1, FAN.length))}>
                →
              </button>
              <button type="button" className="bkm-lbbtn" aria-label="Close" onClick={() => setLb(-1)}>
                ×
              </button>
            </figcaption>
          </figure>
        </div>
      )}

      <div className="bkm-toast" data-on={toast.on ? "" : undefined} role="status" aria-live="polite">
        {toast.text}
      </div>
      <div ref={cursorRef} className="bkm-cursor" aria-hidden="true">
        <span ref={labelRef} className="bkm-clab bkm-mono" />
      </div>
    </section>
  )
}

function ActionEl({ a, className, cursor, children }: { a: Action; className: string; cursor: string; children?: ReactNode }) {
  const props = { className, "data-magnet": "", "data-cursor": cursor }
  if (a.href) {
    return (
      <a href={a.href} onClick={a.onClick} {...props}>
        {children}
      </a>
    )
  }
  return (
    <button type="button" onClick={a.onClick} {...props}>
      {children}
    </button>
  )
}

/* ------------------------------------------------------------- fonts + pictures */
// Subsets of Inter Tight (400, 700) and JetBrains Mono (capitals), SIL OFL 1.1, renamed as the licence asks.

const FONTS =
  "@font-face{font-family:BkmSans;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}" +
  "@font-face{font-family:BkmSans;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}" +
  "@font-face{font-family:BkmMono;font-weight:400 700;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}"

const IMG: Record<string, string> = {
  "a3": "data:image/webp;base64,",
  "b7": "data:image/webp;base64,",
  "b5": "data:image/webp;base64,",
  "s2": "data:image/webp;base64,",
}
